@spec bridge_spec  src=tests/specs/bridge_spec.lua  loc=245  cases=16
@exercises bridge (bridge)
@surface   bridge:tick

# Intent
  Pin-tests for bridge.lua. Every case drives the REAL entry point — tick() ->
  scan -> execute -> write — against a temp spool dir, faking only REAPER's
  EnumerateFiles (the directory-listing seam, exactly as fs_spec does). The
  request/response protocol is thus exercised end to end, not through a
  re-implemented handler.

# Helpers
  @fn tmpDir()  @ 10-12
  @fn writeFile(p, s)  @ 13
  @fn readFile(p)  @ 14-17
  @fn fileExists(p)  @ 18-21
  @fn parseRes(text)  @ 26-32
      -- Parse a res file back into fields. The value section is always one line (render
      -- never emits newlines); print may span lines; an error value carries a
      -- multi-line traceback — all captured by the non-greedy value / greedy print cut.
  @fn runChunk(chunk, opts)  @ 36-54
      -- Plant `chunk` as the sole request, tick the bridge once, return the parsed res.
      -- opts.reaper(r) may add extra REAPER stubs (e.g. Undo_*) before the tick.

# Cases
  @case 'round trip: request executed, response written, request deleted first'  [pure]  @ 58-64
  @case 'chunk sees the Lua stdlib via _G fallback (env holds only handles)'  [pure]  @ 67-72
  @case 'error path carries message and traceback'  [pure]  @ 75-81
  @case 'print() output is captured into the print section'  [pure]  @ 84-89
  @case 'directive --#depth caps render depth'  [pure]  @ 92-97
  @case 'directive --#undo wraps execution in an undo block'  [pure]  @ 100-111
  @case 'render survives a cyclic table'  [pure]  @ 114-119
  @case 'render prints userdata via tostring'  [pure]  @ 122-127
  @case 'render truncates a long string at the default cap'  [pure]  @ 130-135
  @case 'directive --#str widens the string cap'  [pure]  @ 138-144
  @case 'render truncates a wide table with a +N more marker'  [pure]  @ 147-151
  @case 'render stops at the total byte cap'  [pure]  @ 154-162
  @case 'scan invalidates the EnumerateFiles cache (idx -1) before listing'  [pure]  @ 165-184
  @case 'enabling records our named command id, which is all the launcher gets'  [pure]  @ 187-192
  @case 'reload() relaunches on the NEXT tick, once, after the response is written'  [pure]  @ 195-226
  @case 'tick over an empty spool writes nothing and does not error'  [pure]  @ 229-243

# Uses (outbound edges)
  @use call bridge:tick  @ 51,181,213,218,223,240

